    }

    atmosphereRequest.setProtocol(request.getProtocol());

    try {
        atmosphereRequest.setRequestedSessionId(request.getRequestedSessionId());
    } catch (IllegalStateException e) {
        throw new RuntimeException("Unable to get requested session ID from " + request, e);
    }

    try {
