    }

    atmosphereRequest.setScheme(request.getScheme());
    atmosphereRequest.setServerName(request.getServerName());
    atmosphereRequest.setServerPort(request.getServerPort());
    atmosphereRequest.setReader(request.getReader());
    atmosphereRequest.setSecure(request.isSecure());
    atmosphereRequest.setAsyncSupported(request.isAsyncSupported());
