    atmosphereRequest.setRequestURI(request.getRequestURI());
    atmosphereRequest.setRequestedSessionIdFromURL(request.isRequestedSessionIdFromURL());
    atmosphereRequest.setUserPrincipal(request.getUserPrincipal());

