public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null || u.getPath() == null) {
        return Collections.emptyList();
    }

    String path = u.getPath();
    int len = path.length();
    if (len == 0) {
        return Collections.emptyList();
    }

    // Skip leading '/'
    int start = path.charAt(0) == '/' ? 1 : 0;

    List<PathSegmentImpl> segments = new ArrayList<>();
    int pos = start;
    while (pos < len) {
        int segStart = pos;
        while (pos < len && path.charAt(pos) != '/') {
            pos++;
        }
        if (pos >= len) {
            break;
        }
        int segEnd = pos - 1;
        if (decode) {
            segEnd = pos - 1;
            while (segEnd > segStart && path.charAt(segEnd) == '%') {
                segEnd--;
            }
        }
        String segment = path.substring(segStart, segEnd);
        segments.add(new PathSegmentImpl(segment, false));
    }

    return Collections.unmodifiableList(segments);
}
