public void write(final byte[] b, final int off, final int len) throws IOException {
    // Check for null pointer
    if (b == null) {
        throw new NullPointerException("b is null");
    }

    // Check for valid offsets and lengths
    if (off < 0 || len < 0 || off + len > b.length) {
        throw new IndexOutOfBoundsException("Invalid offsets or lengths");
    }

    // Write the data to the stream
    synchronized (this) {
        int bytesRemaining = len;
        int offIdx = off;
        while (bytesRemaining > 0) {
            int numBytes = (int) Math.min(bytesRemaining, this.buf.length - this.count);
            System.arraycopy(b, offIdx, this.buf, this.count, numBytes);
            offIdx += numBytes;
            this.count += numBytes;
            bytesRemaining -= numBytes;
        }
    }
}
