    if (event == null) {
      throw new IllegalArgumentException("event cannot be null");
    }

    // Build the log message
    StringBuilder logMessage = new StringBuilder();
    logMessage.append(event.getLevel());
    logMessage.append(" - ");
    logMessage.append(event.getMessage());
    logMessage.append(" (");
    logMessage.append(event.getThreadName());
    logMessage.append("): ");

    // Add any additional data provided in the event's metadata
    Map<String, Object> metadata = event.getMetadata();
    for (Map.Entry<String, Object> entry : metadata.entrySet()) {
