private String unescapeId(String input) {
    // Regex pattern to match dot escapes in a string, such as "\."
    Pattern DOT_ESCAPE_PATTERN = Pattern.compile("\\\\\\.");

    // Matcher to find dot escapes in the input string
    Matcher matcher = DOT_ESCAPE_PATTERN.matcher(input);

    // Flag to indicate if any dot escapes were found in the input
    boolean hasEscapes = false;

    // Output string buffer to store the unescaped input
    StringBuilder output = new StringBuilder();

    while (matcher.find()) {
        hasEscapes = true;
        // Get the match for the current dot escape in the input
        String match = matcher.group();

        // Replace the dot escape with the unescaped character
        output.append(match, 2, match.length());
    }

    // If there were no dot escapes found, return the original input
    if (!hasEscapes) {
        return input;
    }

    // Return the unescaped output as a new string
    return output.toString();
}
