private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (vertices.size() == 0) {
        return false;
    }
    Set<V> neighbors = new HashSet<>();
    for (V v : vertices) {
        if (neighbors.contains(v)) {
            // Remove the vertex and its neighbors from the set of vertices
            vertices.remove(v);
            neighbors.remove(v);
            continue;
        }
        // Add all neighbors of the current vertex to the set of neighbors
        neighbors.addAll(graph.neighbors(v));
    }
    // Check if the set of neighbors contains all vertices in the original set
    return neighbors.containsAll(vertices);
}
