private static ThreadSnapshot parseThreadSnapshot(String line,List<ProfileAnalyzeTimeRange> timeRanges) {
    // parse line and generate thread snapshot
    int firstSpace = line.indexOf(' ');
    int lastSpace = line.lastIndexOf(' ');
    String threadId = line.substring(0, firstSpace);
    long timestamp = Long.parseLong(line.substring(firstSpace + 1, lastSpace));
    float cpuTime = Float.parseFloat(line.substring(lastSpace + 1));
    ProfileAnalyzeTimeRange matchingTimeRange = findMatchingTimeRange(timeRanges, timestamp);
    ThreadSnapshot snapshot = new ThreadSnapshot(threadId, timestamp, cpuTime, matchingTimeRange);
    return snapshot;
}

private static ProfileAnalyzeTimeRange findMatchingTimeRange(List<ProfileAnalyzeTimeRange> timeRanges, long timestamp) {
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        if (timeRange.contains(timestamp)) {
            return timeRange;
        }
    }
    return null;
}
